<script setup>import{EVENT_FALLBACKS}from'@/features/copy/catalog.js';defineProps({headline:{default:'Algo no cargó bien.'},body:{default:EVENT_FALLBACKS.generic_error.text},actionLabel:{default:'Volver a intentar'},detail:String});defineEmits(['action'])</script><template><section class="error" role="alert"><b>● Error</b><h2>{{headline}}</h2><p>{{body}}</p><code v-if="detail">{{detail}}</code><button v-if="actionLabel" @click="$emit('action')">{{actionLabel}}</button></section></template><style scoped>.error{display:flex;flex-direction:column;gap:10px;padding:16px;border:1px solid color-mix(in srgb,var(--status-destructive) 32%,transparent);border-radius:var(--radius-lg);background:var(--surface-primary);font-family:var(--font-core)}b{color:var(--status-destructive);font-size:12px;text-transform:uppercase}h2{color:var(--text-primary);font-size:20px}p{color:var(--text-secondary);font-size:14px}code{color:var(--text-muted)}button{align-self:flex-start;min-height:44px;padding:0 18px;border:0;border-radius:99px;background:var(--action-secondary-bg);color:var(--text-secondary)}</style>
